solution:
class QueueWithTwoStacks:
    def __init__(self):
        self._inbox = []      # new items are pushed here
        self._outbox = []     # items waiting to leave, with the front of the queue on top

    def push(self, x):
        self._inbox.append(x)

    def pop(self):
        self._refill_outbox()
        return self._outbox.pop()

    def peek(self):
        self._refill_outbox()
        return self._outbox[-1]

    def empty(self):
        return not self._inbox and not self._outbox

    def _refill_outbox(self):
        if not self._outbox:                      # only when it is empty, or newer items would jump the queue
            while self._inbox:
                self._outbox.append(self._inbox.pop())    # pouring one stack into another reverses it
